export function ContextMenu({
  itemLabel = "{{itemLabel}}",
  destructiveLabel = "{{destructiveLabel}}",
  accent = "{{accent}}",
  open = {{open}},
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, width: 280, padding: "10px 12px", background: "#FAF7F2", borderRadius: 10, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <span>{itemLabel}</span>
      <details open={open} style={{ position: "relative" }}>
        <summary aria-label={"More actions for " + itemLabel} style={{ listStyle: "none", cursor: "pointer", padding: "4px 8px", borderRadius: 6, fontSize: 18, lineHeight: 1 }}>&#8942;</summary>
        <div role="group" aria-label={"Actions for " + itemLabel} style={{ position: "absolute", right: 0, top: "calc(100% + 4px)", minWidth: 150, background: "#fff", border: "1px solid rgba(36,20,48,.12)", borderRadius: 10, boxShadow: "0 8px 24px rgba(36,20,48,.14)", padding: 6, display: "flex", flexDirection: "column", gap: 2 }}>
          <button type="button" style={{ textAlign: "left", padding: "8px 10px", borderRadius: 8, border: "none", background: "none", font: "inherit", color: "#241430", cursor: "pointer" }}>Rename</button>
          <button type="button" style={{ textAlign: "left", padding: "8px 10px", borderRadius: 8, border: "none", background: "none", font: "inherit", color: "#241430", cursor: "pointer" }}>Duplicate</button>
          <button type="button" style={{ textAlign: "left", padding: "8px 10px", borderRadius: 8, border: "none", background: "none", font: "inherit", color: "#b3312c", cursor: "pointer" }}>{destructiveLabel}</button>
        </div>
      </details>
    </div>
  );
}
